// .opencode/plugins/canal_buzon.js
// Plugin de recados de Big Pickle.
// Lee recados del canal SIN marcarlos, los inyecta en la sesion,
// y SOLO despues de entregarlos los marca como leidos.
// Si no hay sesion conocida (sessionID vacio), NO toca el canal.

import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const RAIZ = process.cwd();
const CANAL = join(RAIZ, "arnes", "canal.py");
const DIR_MARCAS = join(RAIZ, ".opencode", "marcas_buzon");
const PREFIJO_MARCA = "prt_";

function rutaMarca(id) {
  return join(DIR_MARCAS, PREFIJO_MARCA + id + ".txt");
}

function yaMarcado(id) {
  return existsSync(rutaMarca(id));
}

function dejarMarca(id) {
  if (!existsSync(DIR_MARCAS)) mkdirSync(DIR_MARCAS, { recursive: true });
  writeFileSync(rutaMarca(id), new Date().toISOString(), "utf-8");
}

function leerSinMarcar() {
  const r = spawnSync("python", [CANAL, "leer", "--sin-marcar"], {
    cwd: RAIZ,
    encoding: "utf-8",
  });
  if (r.status !== 0) return [];
  const salida = (r.stdout || "").trim();
  if (!salida) return [];
  try {
    const datos = JSON.parse(salida);
    return Array.isArray(datos) ? datos : [];
  } catch {
    return [];
  }
}

function marcarLeidosEnCanal(rutas) {
  if (!rutas.length) return;
  spawnSync("python", [CANAL, "marcar", ...rutas], {
    cwd: RAIZ,
    encoding: "utf-8",
  });
}

function idInyectado(msg) {
  // Id seguro: sin comilla y sin la palabra Date pegada a canal-.
  const base = String(msg.id || msg.ruta || "recado");
  const limpio = base.replace(/[^A-Za-z0-9_.-]/g, "_");
  return "recado_" + limpio;
}

export const CanalBuzon = async ({ client, directory }) => {
  return {
    "chat.message": async (input, output) => {
      const sessionID = input && input.sessionID ? String(input.sessionID) : "";
      // Sin sesion conocida NO se toca el canal.
      if (!sessionID) return;

      const recados = leerSinMarcar();
      const pendientes = recados.filter((m) => !yaMarcado(m.id || m.ruta));
      if (!pendientes.length) return;

      const entregados = [];
      for (const msg of pendientes) {
        const id = idInyectado(msg);
        const texto = String(msg.texto || msg.mensaje || "");
        output.parts.push({
          type: "text",
          text: "[" + id + "] " + texto,
        });
        dejarMarca(msg.id || msg.ruta);
        entregados.push(msg.ruta);
      }

      // SOLO despues de entregarlos se marcan como leidos en el canal.
      marcarLeidosEnCanal(entregados);
    },
  };
};
